from search_attractions import Attractions
attr = Attractions()

cities = ['Cleveland','Columbus','Cincinnati','Minneapolis']

def is_ascii(s):
    try:
        s.encode('ascii')
        return True
    except Exception:
        return False

for city in cities:
    df = attr.run(city)
    print('\n', city)
    if isinstance(df,str):
        print(df); continue
    df = df[df['Name'].apply(is_ascii)]
    print(df[['Name','Address']].head(10).to_string(index=False))
